@Injectable()
export class AuthService {
  async refresh(userId: string, presented: string) {
    const session = await this.sessions.find(userId, hash(presented));
    if (!session) {
      // reuse of a rotated token => assume theft, kill the family
      await this.sessions.revokeAll(userId);
      throw new ForbiddenException();
    }
    await this.sessions.rotate(session.id, hash(newRefresh)); // one-time use
    return {
      accessToken: this.jwt.sign({ sub: userId }, { expiresIn: '10m' }),
      refreshToken: newRefresh, // set as httpOnly Secure cookie
    };
  }
}

@Injectable()
export class CaslAbilityFactory {
  createForUser(user: User) {
    const { can, cannot, build } = new AbilityBuilder(createMongoAbility);
    if (user.role === Role.Admin) {
      can('manage', 'all');
    } else {
      can('read', 'Post');
      can('update', 'Post', { authorId: user.id }); // attribute rule
      cannot('delete', 'Post', { published: true }); // overrides can
    }
    return build();
  }
}

