// single translation point at the HTTP boundary
@Catch()
export class GlobalFilter implements ExceptionFilter {
  private static readonly MAP: Record<string, number> = {
    INSUFFICIENT_BALANCE: 422,
    DUPLICATE_ENTITY: 409,
    ENTITY_NOT_FOUND: 404,
  };
  catch(err: unknown, host: ArgumentsHost) {
    const res = host.switchToHttp().getResponse();
    const status = err instanceof DomainError
      ? GlobalFilter.MAP[err.code] ?? 400
      : err instanceof HttpException ? err.getStatus() : 500;
    // log ONCE here with correlation id; generic body for 500s
    res.status(status).json({ code: (err as any).code ?? 'INTERNAL', correlationId: res.req.id });
  }
}

